[
  {
    "name": "Judge/Official Titles",
    "description": "Matches persons identified by judicial titles like Richter, Richterin, Mag., Dr., Prof., etc., specifically when preceded by 'durch' (by) or 'hat durch' (has by).",
    "format": "regex",
    "content": "(?:durch\\s+(?:die\\s+)?(?:Richterin|Richter|Vorsitzender|Laienrichter)\\s+)?(?:Mag\\.?\\.?\\.?|Dr\\.?\\.?\\.?|Univ\\.-Prof\\.?|Hon\\.-Prof\\.?|Priv\\.-Doz\\.?|Mag\\.a|Dr\\.in|LL\\.M\\.?)(?:\\s+[A-Z][a-z]+(?:\\s+[A-Z][a-z]+)*)+",
    "priority": 10,
    "output_template": {
      "text": "$0",
      "start": "$start",
      "end": "$end",
      "type": "person"
    },
    "output_key": "entities"
  },
  {
    "name": "Representative Context",
    "description": "Matches persons mentioned as representatives (vertreten durch) or in 'VetR' (Verfahrensbevollm\u00e4chtigter) contexts.",
    "format": "regex",
    "content": "(?:vertreten\\s+durch|VetR)\\s+([A-Z][a-z]+(?:\\s+[A-Z][a-z]+)*)",
    "priority": 7,
    "output_template": {
      "text": "$1",
      "start": "$start",
      "end": "$end",
      "type": "person"
    },
    "output_key": "entities"
  }
]
